use std::time::Duration;

use reqwest::Client;

use crate::config::Config;

use super::error::ApiError;

const BASE_URL: &str = "https://api.screenscraper.fr/api2";

/// HTTP client for the ScreenScraper API with authentication.
#[derive(Debug, Clone)]
pub struct ScreenScraperClient {
    http: Client,
    base_url: String,
    devid: String,
    devpassword: String,
    softname: String,
    ssid: String,
    sspassword: String,
}

impl ScreenScraperClient {
    pub fn new(config: &Config) -> Result<Self, ApiError> {
        let http = Client::builder()
            .timeout(Duration::from_secs(config.network.request_timeout_secs))
            .user_agent(&config.credentials.softname)
            .build()?;

        Ok(Self {
            http,
            base_url: BASE_URL.to_string(),
            devid: config.credentials.devid.clone(),
            devpassword: config.credentials.devpassword.clone(),
            softname: config.credentials.softname.clone(),
            ssid: config.credentials.ssid.clone(),
            sspassword: config.credentials.sspassword.clone(),
        })
    }

    /// Build the base query parameters for every API request.
    fn base_params(&self) -> Vec<(&str, String)> {
        let mut params: Vec<(&str, String)> = vec![
            ("devid", self.devid.clone()),
            ("devpassword", self.devpassword.clone()),
            ("softname", self.softname.clone()),
            ("output", "json".to_string()),
        ];
        if !self.ssid.is_empty() {
            params.push(("ssid", self.ssid.clone()));
        }
        if !self.sspassword.is_empty() {
            params.push(("sspassword", self.sspassword.clone()));
        }
        params
    }

    /// Perform a GET request to a ScreenScraper endpoint and parse JSON response.
    pub async fn get_json<T: serde::de::DeserializeOwned>(
        &self,
        endpoint: &str,
        extra_params: &[(&str, String)],
    ) -> Result<T, ApiError> {
        let url = format!("{}/{}", self.base_url, endpoint);
        let mut params = self.base_params();
        params.extend_from_slice(extra_params);

        tracing::debug!("API request: {} with {} params", endpoint, params.len());

        let response = self.http.get(&url).query(&params).send().await?;

        let status = response.status().as_u16();
        if status != 200 {
            let body = response.text().await.unwrap_or_default();
            return Err(ApiError::from_status(status, &body));
        }

        let body = response.text().await?;
        serde_json::from_str::<T>(&body)
            .map_err(|e| ApiError::Deserialize(format!("{}: {}", e, &body[..body.len().min(200)])))
    }

    /// Perform a raw GET request returning the response for streaming (media downloads).
    pub async fn get_raw(
        &self,
        endpoint: &str,
        extra_params: &[(&str, String)],
        timeout: Duration,
    ) -> Result<reqwest::Response, ApiError> {
        let url = format!("{}/{}", self.base_url, endpoint);
        let mut params = self.base_params();
        params.extend_from_slice(extra_params);

        let response = self.http.get(&url).query(&params).timeout(timeout).send().await?;

        let status = response.status().as_u16();
        if status != 200 {
            let body = response.text().await.unwrap_or_default();
            return Err(ApiError::from_status(status, &body));
        }

        Ok(response)
    }
}

#[cfg(test)]
impl ScreenScraperClient {
    /// Create a client pointing at a custom base URL (for mock server tests).
    pub fn with_base_url(config: &Config, base_url: &str) -> Result<Self, ApiError> {
        let mut client = Self::new(config)?;
        client.base_url = base_url.to_string();
        Ok(client)
    }

    fn test_base_params(&self) -> Vec<(&str, String)> {
        self.base_params()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::Config;

    fn test_config() -> Config {
        let mut config = Config::default();
        config.credentials.devid = "testdev".to_string();
        config.credentials.devpassword = "testpass".to_string();
        config.credentials.softname = "scrauper".to_string();
        config.credentials.ssid = "user".to_string();
        config.credentials.sspassword = "userpass".to_string();
        config
    }

    #[test]
    fn test_new_client() {
        let config = test_config();
        let client = ScreenScraperClient::new(&config);
        assert!(client.is_ok());
    }

    #[test]
    fn test_new_client_empty_creds() {
        let config = Config::default();
        // new() should NOT fail for empty creds - that's validated elsewhere
        // But Config::default() has empty devid/devpassword which is fine for client construction
        let result = ScreenScraperClient::new(&config);
        assert!(result.is_ok());
    }

    #[test]
    fn test_base_params_includes_auth() {
        let config = test_config();
        let client = ScreenScraperClient::new(&config).unwrap();
        let params = client.test_base_params();

        assert!(params.iter().any(|(k, v)| *k == "devid" && v == "testdev"));
        assert!(params.iter().any(|(k, v)| *k == "devpassword" && v == "testpass"));
        assert!(params.iter().any(|(k, v)| *k == "softname" && v == "scrauper"));
        assert!(params.iter().any(|(k, v)| *k == "output" && v == "json"));
        assert!(params.iter().any(|(k, v)| *k == "ssid" && v == "user"));
        assert!(params.iter().any(|(k, v)| *k == "sspassword" && v == "userpass"));
    }

    #[test]
    fn test_base_params_omits_empty_ssid() {
        let mut config = test_config();
        config.credentials.ssid = String::new();
        config.credentials.sspassword = String::new();
        let client = ScreenScraperClient::new(&config).unwrap();
        let params = client.test_base_params();

        assert!(!params.iter().any(|(k, _)| *k == "ssid"));
        assert!(!params.iter().any(|(k, _)| *k == "sspassword"));
    }

    #[test]
    fn test_base_params_count() {
        let config = test_config();
        let client = ScreenScraperClient::new(&config).unwrap();
        let params = client.test_base_params();
        // devid + devpassword + softname + output + ssid + sspassword = 6
        assert_eq!(params.len(), 6);
    }

    #[test]
    fn test_base_params_count_no_user() {
        let mut config = test_config();
        config.credentials.ssid = String::new();
        config.credentials.sspassword = String::new();
        let client = ScreenScraperClient::new(&config).unwrap();
        let params = client.test_base_params();
        // devid + devpassword + softname + output = 4
        assert_eq!(params.len(), 4);
    }

    // --- wiremock integration tests ---

    use std::time::Duration;
    use wiremock::matchers::{method, path, query_param};
    use wiremock::Mock;
    use wiremock::MockServer;
    use wiremock::ResponseTemplate;

    #[tokio::test]
    async fn test_get_json_success() {
        let mock_server = MockServer::start().await;

        Mock::given(method("GET"))
            .and(path("/test_endpoint.php"))
            .respond_with(
                ResponseTemplate::new(200).set_body_json(serde_json::json!({"result": "ok"})),
            )
            .mount(&mock_server)
            .await;

        let config = test_config();
        let client = ScreenScraperClient::with_base_url(&config, &mock_server.uri()).unwrap();
        let result: serde_json::Value = client.get_json("test_endpoint.php", &[]).await.unwrap();

        assert_eq!(result, serde_json::json!({"result": "ok"}));
    }

    #[tokio::test]
    async fn test_get_json_404() {
        let mock_server = MockServer::start().await;

        Mock::given(method("GET"))
            .and(path("/test_endpoint.php"))
            .respond_with(ResponseTemplate::new(404))
            .mount(&mock_server)
            .await;

        let config = test_config();
        let client = ScreenScraperClient::with_base_url(&config, &mock_server.uri()).unwrap();
        let result: Result<serde_json::Value, _> = client.get_json("test_endpoint.php", &[]).await;

        assert!(matches!(result, Err(ApiError::GameNotFound)));
    }

    #[tokio::test]
    async fn test_get_json_429() {
        let mock_server = MockServer::start().await;

        Mock::given(method("GET"))
            .and(path("/test_endpoint.php"))
            .respond_with(ResponseTemplate::new(429))
            .mount(&mock_server)
            .await;

        let config = test_config();
        let client = ScreenScraperClient::with_base_url(&config, &mock_server.uri()).unwrap();
        let result: Result<serde_json::Value, _> = client.get_json("test_endpoint.php", &[]).await;

        assert!(matches!(result, Err(ApiError::RateLimited)));
    }

    #[tokio::test]
    async fn test_get_json_403() {
        let mock_server = MockServer::start().await;

        Mock::given(method("GET"))
            .and(path("/test_endpoint.php"))
            .respond_with(ResponseTemplate::new(403))
            .mount(&mock_server)
            .await;

        let config = test_config();
        let client = ScreenScraperClient::with_base_url(&config, &mock_server.uri()).unwrap();
        let result: Result<serde_json::Value, _> = client.get_json("test_endpoint.php", &[]).await;

        assert!(matches!(result, Err(ApiError::InvalidCredentials)));
    }

    #[tokio::test]
    async fn test_get_json_invalid_json() {
        let mock_server = MockServer::start().await;

        Mock::given(method("GET"))
            .and(path("/test_endpoint.php"))
            .respond_with(ResponseTemplate::new(200).set_body_string("not json"))
            .mount(&mock_server)
            .await;

        let config = test_config();
        let client = ScreenScraperClient::with_base_url(&config, &mock_server.uri()).unwrap();
        let result: Result<serde_json::Value, _> = client.get_json("test_endpoint.php", &[]).await;

        assert!(matches!(result, Err(ApiError::Deserialize(_))));
    }

    #[tokio::test]
    async fn test_get_raw_success() {
        let mock_server = MockServer::start().await;

        Mock::given(method("GET"))
            .and(path("/media_endpoint.php"))
            .respond_with(ResponseTemplate::new(200).set_body_bytes(b"image data".to_vec()))
            .mount(&mock_server)
            .await;

        let config = test_config();
        let client = ScreenScraperClient::with_base_url(&config, &mock_server.uri()).unwrap();
        let response =
            client.get_raw("media_endpoint.php", &[], Duration::from_secs(10)).await.unwrap();
        let bytes = response.bytes().await.unwrap();

        assert_eq!(bytes.as_ref(), b"image data");
    }

    #[tokio::test]
    async fn test_get_raw_401() {
        let mock_server = MockServer::start().await;

        Mock::given(method("GET"))
            .and(path("/media_endpoint.php"))
            .respond_with(ResponseTemplate::new(401))
            .mount(&mock_server)
            .await;

        let config = test_config();
        let client = ScreenScraperClient::with_base_url(&config, &mock_server.uri()).unwrap();
        let result = client.get_raw("media_endpoint.php", &[], Duration::from_secs(10)).await;

        assert!(matches!(result, Err(ApiError::ApiClosedOverloaded)));
    }

    #[tokio::test]
    async fn test_get_json_sends_auth_params() {
        let mock_server = MockServer::start().await;

        Mock::given(method("GET"))
            .and(path("/test_endpoint.php"))
            .and(query_param("devid", "testdev"))
            .and(query_param("devpassword", "testpass"))
            .and(query_param("softname", "scrauper"))
            .and(query_param("output", "json"))
            .respond_with(ResponseTemplate::new(200).set_body_json(serde_json::json!({"ok": true})))
            .mount(&mock_server)
            .await;

        let config = test_config();
        let client = ScreenScraperClient::with_base_url(&config, &mock_server.uri()).unwrap();
        let result: serde_json::Value = client.get_json("test_endpoint.php", &[]).await.unwrap();

        assert_eq!(result, serde_json::json!({"ok": true}));
    }

    #[tokio::test]
    async fn test_get_json_sends_user_params() {
        let mock_server = MockServer::start().await;

        Mock::given(method("GET"))
            .and(path("/test_endpoint.php"))
            .and(query_param("ssid", "user"))
            .and(query_param("sspassword", "userpass"))
            .respond_with(ResponseTemplate::new(200).set_body_json(serde_json::json!({"ok": true})))
            .mount(&mock_server)
            .await;

        let config = test_config();
        let client = ScreenScraperClient::with_base_url(&config, &mock_server.uri()).unwrap();
        let result: serde_json::Value = client.get_json("test_endpoint.php", &[]).await.unwrap();

        assert_eq!(result, serde_json::json!({"ok": true}));
    }

    #[tokio::test]
    async fn test_get_raw_custom_timeout() {
        let mock_server = MockServer::start().await;

        Mock::given(method("GET"))
            .and(path("/media_endpoint.php"))
            .respond_with(ResponseTemplate::new(200).set_body_bytes(b"data".to_vec()))
            .mount(&mock_server)
            .await;

        let config = test_config();
        let client = ScreenScraperClient::with_base_url(&config, &mock_server.uri()).unwrap();
        let response =
            client.get_raw("media_endpoint.php", &[], Duration::from_secs(60)).await.unwrap();
        let bytes = response.bytes().await.unwrap();

        assert_eq!(bytes.as_ref(), b"data");
    }
}

use std::path::PathBuf;

use anyhow::{Context, Result};
use serde::Deserialize;

use crate::models::system::{System, SystemsCache};

use super::client::ScreenScraperClient;
use super::error::ApiError;

// --- Response types ---

/// User info response from ssuserInfos.php
#[derive(Debug, Deserialize)]
pub struct UserInfoResponse {
    pub response: UserInfoInner,
}

#[derive(Debug, Deserialize)]
pub struct UserInfoInner {
    pub ssuser: SsUser,
}

#[allow(dead_code)]
#[derive(Debug, Deserialize)]
pub struct SsUser {
    pub id: Option<String>,
    #[serde(rename = "numid")]
    pub num_id: Option<String>,
    pub niveau: Option<String>,
    pub contribution: Option<String>,
    pub uploadsysteme: Option<String>,
    pub uploadinfos: Option<String>,
    pub romassocaliases: Option<String>,
    pub uploadmedia: Option<String>,
    pub propositionok: Option<String>,
    pub propositionko: Option<String>,
    pub quotareq100: Option<String>,
    pub maxthreads: Option<String>,
    pub maxdownloadspeed: Option<String>,
    pub requeststoday: Option<String>,
    pub requestskotoday: Option<String>,
    pub maxrequestspermin: Option<String>,
    pub maxrequestsperday: Option<String>,
    pub maxrequestskoperday: Option<String>,
    pub visites: Option<String>,
    pub datedernierevisite: Option<String>,
    pub favregion: Option<String>,
}

/// Parsed user info for display.
#[derive(Debug)]
pub struct UserInfo {
    pub username: String,
    pub user_id: String,
    pub level: String,
    pub contribution: String,
    pub max_threads: u32,
    pub max_requests_per_min: u32,
    pub max_requests_per_day: u32,
    pub requests_today: u32,
    pub requests_ko_today: u32,
    pub max_download_speed: u32,
    pub favorite_region: String,
}

impl From<SsUser> for UserInfo {
    fn from(u: SsUser) -> Self {
        Self {
            username: u.id.unwrap_or_default(),
            user_id: u.num_id.unwrap_or_default(),
            level: u.niveau.unwrap_or_default(),
            contribution: u.contribution.unwrap_or_default(),
            max_threads: u.maxthreads.as_deref().unwrap_or("1").parse().unwrap_or(1),
            max_requests_per_min: u
                .maxrequestspermin
                .as_deref()
                .unwrap_or("0")
                .parse()
                .unwrap_or(0),
            max_requests_per_day: u
                .maxrequestsperday
                .as_deref()
                .unwrap_or("0")
                .parse()
                .unwrap_or(0),
            requests_today: u.requeststoday.as_deref().unwrap_or("0").parse().unwrap_or(0),
            requests_ko_today: u.requestskotoday.as_deref().unwrap_or("0").parse().unwrap_or(0),
            max_download_speed: u.maxdownloadspeed.as_deref().unwrap_or("0").parse().unwrap_or(0),
            favorite_region: u.favregion.unwrap_or_default(),
        }
    }
}

/// Infrastructure info response from ssinfraInfos.php
#[derive(Debug, Deserialize)]
pub struct InfraInfoResponse {
    pub response: InfraInfoInner,
}

#[derive(Debug, Deserialize)]
pub struct InfraInfoInner {
    pub ssinfra: SsInfra,
}

#[allow(dead_code)]
#[derive(Debug, Deserialize)]
pub struct SsInfra {
    pub cpu1: Option<String>,
    pub cpu2: Option<String>,
    pub cpu3: Option<String>,
    pub cpu4: Option<String>,
    pub threadsmin: Option<String>,
    pub nbscrapeurs: Option<String>,
    pub apiaccess: Option<String>,
    pub closefornomember: Option<String>,
    pub closeforlevel1member: Option<String>,
}

/// Parsed infra info for display.
#[derive(Debug)]
pub struct InfraInfo {
    pub cpu_loads: Vec<String>,
    pub active_threads: String,
    pub active_scrapers: String,
    pub api_open: bool,
}

impl From<SsInfra> for InfraInfo {
    fn from(i: SsInfra) -> Self {
        let mut cpus = Vec::new();
        if let Some(c) = i.cpu1 {
            cpus.push(format!("CPU1: {}%", c));
        }
        if let Some(c) = i.cpu2 {
            cpus.push(format!("CPU2: {}%", c));
        }
        if let Some(c) = i.cpu3 {
            cpus.push(format!("CPU3: {}%", c));
        }
        if let Some(c) = i.cpu4 {
            cpus.push(format!("CPU4: {}%", c));
        }
        Self {
            cpu_loads: cpus,
            active_threads: i.threadsmin.unwrap_or_default(),
            active_scrapers: i.nbscrapeurs.unwrap_or_default(),
            api_open: i.apiaccess.as_deref() != Some("0"),
        }
    }
}

/// Systems list response from systemesListe.php
#[derive(Debug, Deserialize)]
pub struct SystemsListResponse {
    pub response: SystemsListInner,
}

#[derive(Debug, Deserialize)]
pub struct SystemsListInner {
    pub systemes: Vec<SystemEntry>,
}

#[derive(Debug, Deserialize)]
pub struct SystemEntry {
    pub id: serde_json::Value,
    pub noms: Option<serde_json::Value>,
    pub extensions: Option<String>,
    #[serde(rename = "type")]
    pub system_type: Option<String>,
    pub compagnie: Option<String>,
}

impl SystemEntry {
    pub fn to_system(&self) -> System {
        let id = match &self.id {
            serde_json::Value::Number(n) => n.as_u64().unwrap_or(0),
            serde_json::Value::String(s) => s.parse().unwrap_or(0),
            _ => 0,
        };

        let name = self
            .noms
            .as_ref()
            .and_then(|n| {
                n.get("nom_eu")
                    .or_else(|| n.get("nom_us"))
                    .or_else(|| n.get("nom_wor"))
                    .or_else(|| n.get("nom_jp"))
            })
            .and_then(|v| v.as_str())
            .unwrap_or("Unknown")
            .to_string();

        let extensions = self
            .extensions
            .as_deref()
            .unwrap_or("")
            .split(' ')
            .filter(|s| !s.is_empty())
            .map(|s| s.trim_start_matches('.').to_lowercase())
            .collect();

        System {
            id,
            name,
            extensions,
            system_type: self.system_type.clone().unwrap_or_default(),
            company: self.compagnie.clone(),
        }
    }
}

// --- Client methods ---

impl ScreenScraperClient {
    pub async fn get_user_info(&self) -> Result<UserInfo, ApiError> {
        let resp: UserInfoResponse = self.get_json("ssuserInfos.php", &[]).await?;
        Ok(resp.response.ssuser.into())
    }

    pub async fn get_infra_info(&self) -> Result<InfraInfo, ApiError> {
        let resp: InfraInfoResponse = self.get_json("ssinfraInfos.php", &[]).await?;
        Ok(resp.response.ssinfra.into())
    }

    pub async fn get_systems_list(&self) -> Result<Vec<System>, ApiError> {
        let resp: SystemsListResponse = self.get_json("systemesListe.php", &[]).await?;
        Ok(resp.response.systemes.iter().map(SystemEntry::to_system).collect())
    }
}

// --- Systems cache ---

fn cache_dir() -> PathBuf {
    dirs::config_dir().unwrap_or_else(|| PathBuf::from(".")).join("scrauper")
}

fn systems_cache_path() -> PathBuf {
    cache_dir().join("systems_cache.json")
}

/// Load systems from local cache if fresh (< 7 days).
pub fn load_systems_cache() -> Result<Option<Vec<System>>> {
    let path = systems_cache_path();
    if !path.exists() {
        return Ok(None);
    }

    let content = std::fs::read_to_string(&path).context("Failed to read systems cache")?;
    let cache: SystemsCache =
        serde_json::from_str(&content).context("Failed to parse systems cache")?;

    // Check if cache is still fresh (< 7 days)
    if let Ok(fetched) = chrono::DateTime::parse_from_rfc3339(&cache.fetched_at) {
        let age = chrono::Utc::now() - fetched.to_utc();
        if age.num_days() < 7 {
            return Ok(Some(cache.systems));
        }
    }

    Ok(None)
}

/// Save systems list to local cache.
pub fn save_systems_cache(systems: &[System]) -> Result<()> {
    let dir = cache_dir();
    std::fs::create_dir_all(&dir).context("Failed to create cache directory")?;

    let cache =
        SystemsCache { fetched_at: chrono::Utc::now().to_rfc3339(), systems: systems.to_vec() };

    let json = serde_json::to_string_pretty(&cache).context("Failed to serialize systems cache")?;

    std::fs::write(systems_cache_path(), json).context("Failed to write systems cache")?;

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn test_system_entry_to_system_numeric_id() {
        let entry = SystemEntry {
            id: json!(1),
            noms: Some(json!({"nom_eu": "Super Nintendo"})),
            extensions: Some(".sfc .smc .zip".to_string()),
            system_type: Some("Console".to_string()),
            compagnie: Some("Nintendo".to_string()),
        };
        let sys = entry.to_system();
        assert_eq!(sys.id, 1);
        assert_eq!(sys.name, "Super Nintendo");
        assert_eq!(sys.extensions, vec!["sfc", "smc", "zip"]);
        assert_eq!(sys.system_type, "Console");
        assert_eq!(sys.company, Some("Nintendo".to_string()));
    }

    #[test]
    fn test_system_entry_to_system_string_id() {
        let entry = SystemEntry {
            id: json!("42"),
            noms: Some(json!({"nom_us": "Genesis"})),
            extensions: Some(".md .bin".to_string()),
            system_type: None,
            compagnie: None,
        };
        let sys = entry.to_system();
        assert_eq!(sys.id, 42);
        assert_eq!(sys.name, "Genesis");
        assert_eq!(sys.extensions, vec!["md", "bin"]);
    }

    #[test]
    fn test_system_entry_name_fallback_order() {
        // Falls back: eu -> us -> wor -> jp
        let entry = SystemEntry {
            id: json!(1),
            noms: Some(json!({"nom_jp": "ファミコン", "nom_wor": "NES World"})),
            extensions: Some(".nes".to_string()),
            system_type: None,
            compagnie: None,
        };
        let sys = entry.to_system();
        assert_eq!(sys.name, "NES World");

        let entry2 = SystemEntry {
            id: json!(1),
            noms: Some(json!({"nom_jp": "ファミコン"})),
            extensions: None,
            system_type: None,
            compagnie: None,
        };
        assert_eq!(entry2.to_system().name, "ファミコン");
    }

    #[test]
    fn test_system_entry_missing_noms() {
        let entry = SystemEntry {
            id: json!(1),
            noms: None,
            extensions: None,
            system_type: None,
            compagnie: None,
        };
        let sys = entry.to_system();
