        let call_count = std::sync::Arc::new(std::sync::atomic::AtomicU32::new(0));
        let cc = call_count.clone();

        let result = with_retry(&config, || {
            let count = cc.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            async move {
