        let result = lookup_game(&client, &rom, Some(&hashes), 1, &config, false).await;

        assert!(result.is_err());
        assert!(
            matches!(result.unwrap_err(), crate::api::error::ApiError::InvalidCredentials),
            "Expected InvalidCredentials error"
        );
    }
}

