        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();

        let path = dir.join("test.bin");
        std::fs::write(&path, b"deterministic content").unwrap();

        let h1 = hash_rom_blocking(&path, 300).unwrap().unwrap();
